package com.andye.warmod.radar.station.client;import com.andye.warmod.block.entity.RadarStationBlockEntity;import com.andye.warmod.radar.station.RadarSweepMath;import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.renderer.SubmitNodeCollector;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.client.renderer.feature.ModelFeatureRenderer;import net.minecraft.client.renderer.state.level.CameraRenderState;import net.minecraft.world.phys.Vec3;import org.jspecify.annotations.Nullable;public final class RadarStationBlockEntityRenderer implements BlockEntityRenderer<RadarStationBlockEntity,RadarStationRenderState>{public RadarStationBlockEntityRenderer(BlockEntityRendererProvider.Context c){}@Override public RadarStationRenderState createRenderState(){return new RadarStationRenderState();}@Override public void extractRenderState(RadarStationBlockEntity be,RadarStationRenderState s,float partial,Vec3 camera,ModelFeatureRenderer.@Nullable CrumblingOverlay overlay){BlockEntityRenderer.super.extractRenderState(be,s,partial,camera,overlay);double time=be.getLevel()==null?0:be.getLevel().getGameTime()+partial;s.sweepAngle=RadarSweepMath.angleDegrees(time,be.phaseOffset());s.warningActive=be.warningActive();}@Override public void submit(RadarStationRenderState s,PoseStack pose,SubmitNodeCollector collector,CameraRenderState camera){RadarDishRenderer.submit(s,pose,collector);}@Override public int getViewDistance(){return 192;}}